DECLARE @TemplateID_0b6e9a1f92cf UNIQUEIDENTIFIER,
@TypeID_0b6e9a1f92cf UNIQUEIDENTIFIER,
@TemplateText_0b6e9a1f92cf NVARCHAR(MAX),
